{
  "files.eol": "\n",
  "files.trimTrailingWhitespace": true,
  "files.insertFinalNewline": true,

  // L5X is XML. Without this, fragments open as plain text and the outline,
  // folding and tag matching that make a review tractable are all unavailable.
  "files.associations": {
    "*.L5X": "xml",
    "*.tests.yaml": "yaml"
  },

  // Assembled artifacts and the vector index are generated. Showing them in
  // search results buries the reviewable source.
  "search.exclude": {
    "build/**": true,
    ".rag/**": true,
    ".venv/**": true,
    "**/bin/**": true,
    "**/obj/**": true
  },
  "files.watcherExclude": {
    "build/**": true,
    ".rag/**": true,
    ".venv/**": true
  },

  "[xml]": {
    "editor.tabSize": 2,
    // Never reformat an L5X fragment. Whitespace inside it is part of the
    // byte-exact round trip, and a formatter will break assembly.
    "editor.formatOnSave": false
  },
  "[python]": {
    "editor.formatOnSave": true,
    "editor.defaultFormatter": "charliermarsh.ruff",
    "editor.codeActionsOnSave": {
      "source.organizeImports.ruff": "explicit"
    },
    "editor.insertSpaces": false,
    "editor.tabSize": 4
  },

  "python.defaultInterpreterPath": "${workspaceFolder}/.venv/bin/python",
  "python.testing.pytestEnabled": true,
  "python.testing.pytestArgs": ["tools"],

  "yaml.schemas": {
    "https://json.schemastore.org/github-workflow.json": ".github/workflows/*.yml"
  },

  "git.autoRepositoryDetection": "subFolders",
  "git.repositoryScanMaxDepth": 5,

  "dotnet.defaultSolution": "disable"
}

